 "content": "from math import gcd
from functools import reduce

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The small color key uses colors 1-7; the large template is color 8.
    key_cells = [(r, c) for r in range(h) for c in range(w) if 0 < grid[r][c] < 8]
    if not key_cells:
        return out
    r0 = min(r for r, c in key_cells); r1 = max(r for r, c in key_cells)
    c0 = min(c for r, c in key_cells); c1 = max(c for r, c in key_cells)
    key = [ [grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1) ]
    rotated = [list(row) for row in zip(*key[::-1])]  # clockwise 90 degrees

    # The 8-pattern is an enlargement of the key mask; infer its square cell scale
    # from the gcd of contiguous 8-run lengths.
    runs = []
    for row in grid:
        n = 0
        for v in row + [0]:
            if v == 8:
                n += 1
            elif n:
                runs.append(n); n = 0
    for c in range(w):
        n = 0
        for r in range(h):
            if grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n); n = 0
        if n:
            runs.append(n)
    scale = reduce(gcd, runs) if runs else 1
    mask_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    mr0 = min(r for r, c in mask_cells); mc0 = min(c for r, c in mask_cells)
    for i, row in enumerate(rotated):
        for j, color in enumerate(row):
            if color:
                for dr in range(scale):
                    for dc in range(scale):
                        r, c = mr0 + i * scale + dr, mc0 + j * scale + dc
                        if r < h and c < w and grid[r][c] == 8:
                            out[r][c] = color
    return out
